CREATE AGGREGATION POLICY my_policy AS ()
  RETURNS AGGREGATION_CONSTRAINT ->
  AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 5);

CREATE AGGREGATION POLICY my_policy AS ()
  RETURNS AGGREGATION_CONSTRAINT ->
    CASE
      WHEN CURRENT_ROLE() = 'ADMIN'
        THEN NO_AGGREGATION_CONSTRAINT()
      ELSE AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 5)
    END;

CREATE OR REPLACE AGGREGATION POLICY my_db.my_schema.my_policy AS ()
  RETURNS AGGREGATION_CONSTRAINT ->
  AGGREGATION_CONSTRAINT(MIN_GROUP_SIZE => 10)
  COMMENT = 'Groups must have at least 10 rows';

CREATE AGGREGATION POLICY IF NOT EXISTS my_policy AS ()
  RETURNS AGGREGATION_CONSTRAINT -> NO_AGGREGATION_CONSTRAINT();
